import assert from 'node:assert/strict';
import { after, before, describe, it } from 'node:test';
import { api, startTestServer, validShipment, type TestServer } from './helpers.ts';

// 5k shipments like staging. The list must only compute etas for the returned page (limit),
// never for the whole dataset, and must not cache them (see shipments-list-eta.test.ts).
describe('GET /shipments with 5000 shipments', () => {
  let srv: TestServer;

  before(async () => {
    srv = await startTestServer();
    const carriers = ['DHL', 'DPD', 'UPS'];
    for (let i = 0; i < 5000; i++) {
      srv.store.addShipment({
        trackingNumber: `BULK${i}`,
        carrier: carriers[i % 3],
        serviceLevel: 'standard',
        recipient: validShipment().recipient,
      } as any);
    }
  });

  after(async () => {
    await srv.close();
  });

  it('returns only the default page of 50, each with an eta', async () => {
    const res = await api(srv.url, 'GET', '/shipments');
    assert.equal(res.body.count, 50);
    assert.equal(res.body.items.length, 50);
    for (const item of res.body.items) assert.match(item.eta, /^\d{4}-\d{2}-\d{2}$/);
  });

  it('caps limit at 500', async () => {
    const res = await api(srv.url, 'GET', '/shipments?limit=100000');
    assert.equal(res.body.count, 500);
  });

  it('answers well within a generous time budget', async () => {
    await api(srv.url, 'GET', '/shipments');
    const start = performance.now();
    for (let i = 0; i < 10; i++) await api(srv.url, 'GET', '/shipments');
    const avg = (performance.now() - start) / 10;
    assert.ok(avg < 100, `average ${avg.toFixed(1)} ms per request`);
  });
});
